INSERT INTO speed_reading.exercises(id,exercise_type_id,title,description,type_code,difficulty_level,configuration_json,target_age_group_id,creator_id,is_active,created_at,created_by,version,is_deleted)
SELECT (item->>'id')::uuid,t.id,item->>'title',item->>'description',item->>'type',1,item->'configuration',(item->>'targetAgeGroupId')::uuid,'b993e2f8-3948-49bd-9cbd-463e8771c20d'::uuid,true,now(),'system:assessment-v1',1,false FROM desired_assessment d JOIN speed_reading.exercise_types t ON t.name=item->>'type' AND t.is_active AND NOT t.is_deleted ON CONFLICT(id) DO NOTHING;
CREATE TEMP TABLE desired_templates AS SELECT item FROM jsonb_array_elements($templates$[{"age": "10000000-0000-0000-0000-000000000001", "plan": {"week1": [{"exerciseId": "99b0a038-90b9-5156-b803-f96d30753499", "type": "Comprehension", "difficulty": 1, "displayOrder": 1}, {"exerciseId": "82087c90-eb56-587a-b064-cdc27e15f14b", "type": "Tachistoscope", "difficulty": 1, "displayOrder": 2}, {"exerciseId": "dc182755-52fe-5b86-be96-ba98fbcd04b9", "type": "VisualExpansion", "difficulty": 1, "displayOrder": 3}]}}, {"age": "10000000-0000-0000-0000-000000000002", "plan": {"week1": [{"exerciseId": "4d7c5eb7-2a1e-5900-b4ac-bdf3add28872", "type": "Comprehension", "difficulty": 1, "displayOrder": 1}, {"exerciseId": "291705e1-254f-5379-aecd-c033901c276d", "type": "Tachistoscope", "difficulty": 1, "displayOrder": 2}, {"exerciseId": "0f67593d-efd9-5f0d-814b-1f7d2692a48f", "type": "VisualExpansion", "difficulty": 1, "displayOrder": 3}]}}, {"age": "10000000-0000-0000-0000-000000000004", "plan": {"week1": [{"exerciseId": "bd64c53c-c379-5a42-bcfc-a0f076189520", "type": "Comprehension", "difficulty": 1, "displayOrder": 1}, {"exerciseId": "4dd52a35-bbee-512a-914a-8f471438c528", "type": "Tachistoscope", "difficulty": 1, "displayOrder": 2}, {"exerciseId": "39b33543-b617-5e3e-a6fe-06d82b58137b", "type": "VisualExpansion", "difficulty": 1, "displayOrder": 3}]}}, {"age": "10000000-0000-0000-0000-000000000003", "plan": {"week1": [{"exerciseId": "705e471b-ec39-508d-aa84-dd5bee4b6bcf", "type": "Comprehension", "difficulty": 1, "displayOrder": 1}, {"exerciseId": "9ca42784-5cdb-5aaf-be5b-d0f3924ecdeb", "type": "Tachistoscope", "difficulty": 1, "displayOrder": 2}, {"exerciseId": "c5d9326d-2097-51f7-974f-5b660847c831", "type": "VisualExpansion", "difficulty": 1, "displayOrder": 3}]}}]$templates$::jsonb) item;
UPDATE speed_reading.program_templates p SET "WeeklyPatternJson"=d.item->'plan',"InitialDifficultyLevel"=1,"MaxDifficultyLevel"=1,"WeeksPerDifficultyIncrease"=0,"Description"='Üç zorunlu görev: mevcut metin ve tüm soruları, Takistoskop ve Görsel Genişleme.',updated_at=now(),updated_by='system:assessment-v1',version=p.version+1 FROM desired_templates d WHERE p."TargetAgeGroupConfigurationId"=(d.item->>'age')::uuid AND p."IsAssessment" AND p."IsActive" AND NOT p."IsDeleted";
DO $$ BEGIN
IF (SELECT count(*) FROM desired_assessment d JOIN speed_reading.exercises e ON e.id=(item->>'id')::uuid WHERE e.is_active AND NOT e.is_deleted AND e.configuration_json=item->'configuration')<>12 THEN RAISE EXCEPTION 'Assessment catalog verification failed'; END IF;
IF (SELECT count(*) FROM speed_reading.program_templates WHERE "IsAssessment" AND "IsActive" AND NOT "IsDeleted" AND jsonb_array_length("WeeklyPatternJson"->'week1')=3)<>4 THEN RAISE EXCEPTION 'Expected four three-exercise templates'; END IF;
END $$;
SELECT "Name",jsonb_array_length("WeeklyPatternJson"->'week1') FROM speed_reading.program_templates WHERE "IsAssessment" AND "IsActive" AND NOT "IsDeleted";
COMMIT;
